import{_ as t,o as i,c as n,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Điều hướng, bố cục và data demo liên kết","description":"","frontmatter":{},"headers":[],"relativePath":"feature/navigation-ux-linked-demo-data/spec.md","filePath":"feature/navigation-ux-linked-demo-data/spec.md"}'),o={name:"feature/navigation-ux-linked-demo-data/spec.md"};function a(d,e,l,h,r,s){return i(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="đieu-huong-bo-cuc-va-data-demo-lien-ket" tabindex="-1">Điều hướng, bố cục và data demo liên kết <a class="header-anchor" href="#đieu-huong-bo-cuc-va-data-demo-lien-ket" aria-label="Permalink to &quot;Điều hướng, bố cục và data demo liên kết&quot;">​</a></h1><p>&gt; Trạng thái: đã duyệt. Ngày: 2026-11-04. Phạm vi: <code>brandhub-mobile-app</code>, <code>brandhub-web</code>, <code>brandhub-business-service</code>.</p><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Người dùng phải luôn biết mình đang ở đâu, quay lại được, và thấy biểu đồ có số liệu khi đăng nhập bằng bất kỳ tài khoản demo nào. Hiện có bốn vấn đề:</p><ol><li>8 màn Admin trên mobile không có nút quay lại.</li><li>Mobile không có tab dưới; trang More có 22 mục; có hai lối &quot;Cài đặt&quot; dẫn tới hai màn khác nhau.</li><li>Client không có màn hồ sơ trên mobile, dù web có.</li><li>Tài khoản demo không cùng một tổ chức; biểu đồ gần như trống.</li></ol><h2 id="_2-hien-trang-đa-xac-minh" tabindex="-1">2. Hiện trạng đã xác minh <a class="header-anchor" href="#_2-hien-trang-đa-xac-minh" aria-label="Permalink to &quot;2. Hiện trạng đã xác minh&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Hạng mục</th><th style="text-align:left;">Bằng chứng</th></tr></thead><tbody><tr><td style="text-align:left;">Thiếu back</td><td style="text-align:left;">Users, Moderation, Revenue, Notifications, MailTemplates, Reports, SystemHealth, CreditPrices dùng <code>showDrawerButton={false}</code> và không có <code>canGoBack</code></td></tr><tr><td style="text-align:left;">Overview Admin</td><td style="text-align:left;">9 chip là <code>Text</code> có <code>onPress</code>, đè lên thẻ số liệu; đăng xuất nằm cuối trang cuộn; không có biểu đồ</td></tr><tr><td style="text-align:left;">Web Admin</td><td style="text-align:left;"><code>AdminSidebar</code> đã đủ lối đi. Breadcrumb thiếu <code>crawl</code> và <code>trendPipeline</code> trong <code>Navbar.tsx</code> nên hai trang này hiện sai tên</td></tr><tr><td style="text-align:left;">Web, sidebar trong Workspace</td><td style="text-align:left;">Nhóm <code>create</code> có 13 mục trên một danh sách phẳng</td></tr><tr><td style="text-align:left;">Web quick login</td><td style="text-align:left;"><code>landingPath</code> của Client không bao giờ chạy vì nhánh <code>workspaceRole</code> được xét trước</td></tr><tr><td style="text-align:left;">Hồ sơ Client</td><td style="text-align:left;">Web: <code>/workspaces/:id/client-profile</code>. Mobile: không có màn; <code>clientProfileService</code> thiếu hàm đổi hồ sơ cho Workspace</td></tr><tr><td style="text-align:left;">Vai trò Owner</td><td style="text-align:left;"><code>WorkspaceServiceImpl</code> chỉ trả <code>OWNER</code> khi không có dòng <code>workspace_members</code>. Seed cho <code>user177</code> làm <code>MANAGER</code> ở 8 Workspace, nên Owner bị coi là Manager</td></tr><tr><td style="text-align:left;">Tài khoản</td><td style="text-align:left;"><code>user177</code> không sở hữu Circus Digital (chủ là <code>user11</code>). Nút Creator: web <code>user13</code>, mobile <code>user1</code></td></tr><tr><td style="text-align:left;">Hồ sơ Client trong seed</td><td style="text-align:left;"><code>user59</code> có 15 hồ sơ; Workspace &quot;TH True Milk&quot; gắn hồ sơ &quot;Vietjet Air&quot;</td></tr><tr><td style="text-align:left;">Số liệu</td><td style="text-align:left;">10 Workspace có tổng 1 task; 25 user cùng tạo ngày 2026-10-22; <code>billing_orders</code>, <code>billing_payments</code>, <code>content_moderation_reviews</code>, <code>admin_notifications</code> bằng 0; strike 0/0/0; MRR 0 và <code>activeSubscriptions</code> 0 dù có 4 subscription <code>ACTIVE</code></td></tr><tr><td style="text-align:left;">Seed hiện có</td><td style="text-align:left;"><code>dev-quick-login.sql</code> chưa áp dụng trên DB local; <code>TaskSampleSeeder</code> chỉ seed cho Workspace của script đó và hardcode UUID user; cả hai còn Livestream</td></tr></tbody></table><h2 id="_3-user-story" tabindex="-1">3. User Story <a class="header-anchor" href="#_3-user-story" aria-label="Permalink to &quot;3. User Story&quot;">​</a></h2><ul><li>Là <code>Admin</code>, tôi chuyển nhanh giữa các khu vực và quay lại từ mọi màn con.</li><li>Là <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, tôi có thanh tab đúng vai trò và tới các chức năng chính trong tối đa 2 lần bấm.</li><li>Là <code>Client</code>, tôi xem, sửa hồ sơ thương hiệu và đổi hồ sơ đại diện cho Workspace ngay trên mobile.</li><li>Là dev, tôi đăng nhập nhanh bằng 5 tài khoản trên web hoặc mobile và thấy cùng một tổ chức, cùng một bộ số liệu.</li></ul><h2 id="_4-acceptance-criteria" tabindex="-1">4. Acceptance Criteria <a class="header-anchor" href="#_4-acceptance-criteria" aria-label="Permalink to &quot;4. Acceptance Criteria&quot;">​</a></h2><h3 id="_4-1-mobile-admin" tabindex="-1">4.1 Mobile: Admin <a class="header-anchor" href="#_4-1-mobile-admin" aria-label="Permalink to &quot;4.1 Mobile: Admin&quot;">​</a></h3><ul><li>Thanh tab dưới: Tổng quan, Người dùng, Kiểm duyệt, Doanh thu, Thêm.</li><li>&quot;Thêm&quot; chứa: Email/Thông báo, Mẫu email, Báo cáo, Giám sát hệ thống, Bảng giá Credit, Cài đặt, Đăng xuất.</li><li>Mọi màn không phải gốc của tab có nút back trên header. Màn gốc của tab không hiện back.</li><li>Bỏ khối chip và link &quot;Người dùng →&quot; ở Overview. Đăng xuất chỉ ở &quot;Thêm&quot;.</li><li>Overview và Doanh thu có biểu đồ tương đương web, dùng API <code>/admin/statistics</code> và <code>/admin/revenue</code> đã có.</li></ul><h3 id="_4-2-mobile-nguoi-dung-thuong" tabindex="-1">4.2 Mobile: người dùng thường <a class="header-anchor" href="#_4-2-mobile-nguoi-dung-thuong" aria-label="Permalink to &quot;4.2 Mobile: người dùng thường&quot;">​</a></h3><ul><li>Tab dưới theo quyền trong <code>navAccess.ts</code>: <ul><li><code>Manager</code>, <code>Creator</code>, <code>Client</code>: Tổng quan, Task, Lịch, Chat, Thêm.</li><li><code>Owner</code>: Tổng quan, Task, Thêm.</li></ul></li><li>Drawer chỉ còn nhiệm vụ đổi Agency/Workspace, tìm nhanh và chọn theme, ngôn ngữ.</li><li>Trang &quot;Thêm&quot; chia nhóm, mỗi vai trò thấy tối đa 12 mục. Bỏ các mục trùng lối: &quot;Mời thành viên mới&quot; chuyển vào màn Thành viên; AI Video, AI Caption và Lịch sử video chuyển vào AI Hub.</li><li>Chỉ còn một lối &quot;Cài đặt&quot;. Đăng xuất nằm trong đó.</li><li><code>GlobalFab</code> không che tab dưới.</li></ul><h3 id="_4-3-mobile-chia-lai-nut-tren-man-qua-tai" tabindex="-1">4.3 Mobile: chia lại nút trên màn quá tải <a class="header-anchor" href="#_4-3-mobile-chia-lai-nut-tren-man-qua-tai" aria-label="Permalink to &quot;4.3 Mobile: chia lại nút trên màn quá tải&quot;">​</a></h3><p>Xem từng màn rồi mới chia, theo quy tắc: mỗi màn một hành động chính, hành động phụ vào menu, hành động phá huỷ để riêng. Vùng chạm tối thiểu 44×44. Danh sách màn cần xem: AgencyDetail, TaskDetail, SecuritySettings, AccountSettings, MediaLibrary, AdminUserStrikes, ContentRequestDetail, CameraRecord. Không đổi logic nghiệp vụ.</p><h3 id="_4-4-mobile-ho-so-client" tabindex="-1">4.4 Mobile: hồ sơ Client <a class="header-anchor" href="#_4-4-mobile-ho-so-client" aria-label="Permalink to &quot;4.4 Mobile: hồ sơ Client&quot;">​</a></h3><ul><li>Màn <code>ClientProfile</code> chỉ cho <code>Client</code>, có trong &quot;Thêm&quot;.</li><li>Xem, sửa hồ sơ hiện tại của Workspace và đổi sang hồ sơ khác của mình, tương đương trang web.</li><li>Có đủ trạng thái đang tải, lỗi, trống.</li></ul><h3 id="_4-5-web" tabindex="-1">4.5 Web <a class="header-anchor" href="#_4-5-web" aria-label="Permalink to &quot;4.5 Web&quot;">​</a></h3><ul><li>Sidebar trong Workspace: nhóm <code>create</code> chia thành các nhóm con thu gọn được. Không xoá route nào.</li><li>Sửa breadcrumb Admin cho <code>crawl</code> và <code>trendPipeline</code>.</li><li>Bỏ <code>landingPath</code> không có tác dụng trong <code>DevQuickLogin</code>.</li><li>Audit bố cục và nút trên các trang web theo cùng quy tắc mục 4.3. Danh sách trang quá tải được liệt kê trong <code>plan.md</code>.</li></ul><h3 id="_4-6-data-demo" tabindex="-1">4.6 Data demo <a class="header-anchor" href="#_4-6-data-demo" aria-label="Permalink to &quot;4.6 Data demo&quot;">​</a></h3><ul><li>5 tài khoản giữ nguyên email, dùng chung trên web và mobile: <code>admin@</code>, <code>user177@</code>, <code>user1@</code>, <code>user13@</code>, <code>user59@</code> thuộc <code>demo.brandhub.test</code>. Sửa nút Creator trên mobile thành <code>user13@</code>.</li><li><code>user177@</code> là <code>Owner</code> của agency demo và không có dòng <code>workspace_members</code> trong đó, để API trả <code>OWNER</code>.</li><li><code>user1@</code> là <code>Manager</code>, <code>user13@</code> là <code>Creator</code>, <code>user59@</code> là <code>Client</code> trong cùng Workspace &quot;TH True Milk x Circus Digital&quot;. Hồ sơ Client của Workspace này là &quot;TH True Milk&quot;.</li><li>Mọi biểu đồ của Admin và của các vai trò có số liệu khác 0: <ul><li>User đăng ký trải đều 120 ngày; có đủ trạng thái tài khoản; có strike và chế tài.</li><li>Đơn hàng và thanh toán SePay đã xác minh trong <code>billing_*</code>, có kỳ thuê bao hiện tại, MRR khác 0. Mọi dòng có <code>merchant_account=&#39;DEMO&#39;</code>.</li><li>Hàng đợi kiểm duyệt, thông báo Admin, mức dùng AI credit.</li><li>Task đủ 4 trạng thái, có hạn trong 6 tháng qua, giao cho <code>user13@</code> và <code>user1@</code>.</li><li>Bài đăng đủ trạng thái, chỉ trên Facebook, Instagram, TikTok, Threads.</li></ul></li><li>Không có Livestream trong data mới; xoá Livestream khỏi <code>dev-quick-login.sql</code> và <code>TaskSampleSeeder</code>.</li><li><code>activeSubscriptions</code> bằng 0 không phải bug: <code>AdminRevenueService</code> chỉ tính kỳ <code>CURRENT</code> có đơn <code>FULFILLED</code> và thanh toán <code>VERIFIED</code>, trong khi DB không có các dòng này và subscription ở <code>REVIEW_REQUIRED</code>. Seed các dòng đó; subscription của agency demo chuyển sang <code>READY</code>. Không đổi logic tính doanh thu.</li><li>Seed mặc định (<code>SubscriptionCreditSeeder</code>) vẫn không tạo đơn hàng giả; data doanh thu chỉ nằm trong profile tuỳ chọn <code>seed-linked-demo</code>.</li></ul><h3 id="_4-7-an-toan-khi-seed" tabindex="-1">4.7 An toàn khi seed <a class="header-anchor" href="#_4-7-an-toan-khi-seed" aria-label="Permalink to &quot;4.7 An toàn khi seed&quot;">​</a></h3><ul><li>Chạy lại nhiều lần không tạo trùng, không ghi đè data thật. ID cố định, gắn nhãn <code>seedTag</code> để xoá được đúng phần đã seed.</li><li>Có lệnh gỡ data đã seed, xoá theo <code>seedTag</code>.</li><li>Không chạy khi profile là <code>prod</code> hoặc <code>production</code>.</li><li>Trước khi ghi Atlas, in ra số bản ghi sẽ thêm và ghi <code>seed_runs</code>.</li></ul><h3 id="_4-8-đa-ngon-ngu" tabindex="-1">4.8 Đa ngôn ngữ <a class="header-anchor" href="#_4-8-đa-ngon-ngu" aria-label="Permalink to &quot;4.8 Đa ngôn ngữ&quot;">​</a></h3><ul><li>Mobile: chuỗi mới dùng <code>tr()</code>, thêm vào <code>locales/en.json</code>.</li><li>Web: khoá mới thêm đồng thời vào <code>vi.json</code> và <code>en.json</code>, namespace <code>nav.*</code>, <code>admin.navigation.*</code>, <code>clientProfile.*</code>.</li></ul><h3 id="_4-9-light-dark-mode" tabindex="-1">4.9 Light/Dark mode <a class="header-anchor" href="#_4-9-light-dark-mode" aria-label="Permalink to &quot;4.9 Light/Dark mode&quot;">​</a></h3><p>Chỉ dùng token theme sẵn có (<code>palette</code>, biến CSS). Biểu đồ mới dùng màu từ <code>palette</code>, kiểm tra ở cả 2 theme.</p><h2 id="_5-ui-ux" tabindex="-1">5. UI/UX <a class="header-anchor" href="#_5-ui-ux" aria-label="Permalink to &quot;5. UI/UX&quot;">​</a></h2><p>Giữ nguyên ngôn ngữ thiết kế hiện có; đây là tinh chỉnh, không phải đổi giao diện. Kiểm theo <code>ui-ux-pro-max</code> (back dự đoán được, tối đa 5 tab, vùng chạm 44 px) và <code>impeccable</code> chế độ Operate.</p><h2 id="_6-api-contract" tabindex="-1">6. API Contract <a class="header-anchor" href="#_6-api-contract" aria-label="Permalink to &quot;6. API Contract&quot;">​</a></h2><p>Không thêm API. Dùng lại <code>/api/v1/admin/statistics</code>, <code>/api/v1/admin/revenue</code>, <code>/api/v1/client-profile/*</code> và endpoint đổi hồ sơ mà <code>workspaceService.switchMyClientProfile</code> trên web đang gọi.</p><h2 id="_7-error-handling-va-edge-cases" tabindex="-1">7. Error Handling và Edge Cases <a class="header-anchor" href="#_7-error-handling-va-edge-cases" aria-label="Permalink to &quot;7. Error Handling và Edge Cases&quot;">​</a></h2><ul><li>Link sâu từ thông báo vào màn con vẫn có back về màn gốc của tab.</li><li>Đổi Workspace khi đang ở tab: về Tổng quan của Workspace mới.</li><li>Đổi vai trò làm một tab biến mất: chuyển về Tổng quan.</li><li><code>Client</code> chưa có hồ sơ trong Workspace: hiện trạng thái trống và danh sách đổi hồ sơ.</li><li><code>Client</code> chỉ có một hồ sơ: ẩn khối đổi hồ sơ.</li><li>Package chưa duyệt: web giữ nguyên hard gate hiện tại; mobile không nới quyền.</li><li>Giữ nguyên <code>withAccess</code> khi vào thẳng màn không được phép.</li></ul><h2 id="_8-ui-states" tabindex="-1">8. UI States <a class="header-anchor" href="#_8-ui-states" aria-label="Permalink to &quot;8. UI States&quot;">​</a></h2><p>Mỗi màn mới hoặc đổi đều có đang tải, lỗi kèm thử lại, trống, có dữ liệu. Biểu đồ không có dữ liệu hiện thông báo trống, không vẽ đường phẳng.</p><h2 id="_9-test-cases-so-bo" tabindex="-1">9. Test Cases sơ bộ <a class="header-anchor" href="#_9-test-cases-so-bo" aria-label="Permalink to &quot;9. Test Cases sơ bộ&quot;">​</a></h2><ul><li>Mở mỗi màn Admin từ tab và &quot;Thêm&quot;, bấm back, về đúng màn trước.</li><li>Đăng nhập nhanh từng vai trò trên mobile và web: thấy đúng tab, đúng vai trò, đúng Workspace.</li><li><code>Owner</code> thấy Gói cước và Hóa đơn; <code>Creator</code> không thấy.</li><li><code>Client</code> sửa hồ sơ, đổi hồ sơ; web thấy kết quả tương tự.</li><li>Chạy seed 2 lần: số bản ghi không đổi. Chạy lệnh gỡ: data seed hết, data khác còn nguyên.</li><li>Tất cả biểu đồ có số liệu. Đổi ngôn ngữ và theme không vỡ UI.</li><li>Chạy jest, lint, tsc của mobile và web; test seed của business-service.</li></ul><h2 id="_10-definition-of-done" tabindex="-1">10. Definition of Done <a class="header-anchor" href="#_10-definition-of-done" aria-label="Permalink to &quot;10. Definition of Done&quot;">​</a></h2><p>Toàn bộ mục 4 đạt; test tự động qua; đã chạy thử 5 vai trò trên emulator và trình duyệt, có ảnh chụp; <code>plan.md</code>, <code>task.md</code>, <code>test.md</code> được cập nhật. Không commit khi chưa được yêu cầu.</p><h2 id="_11-out-of-scope" tabindex="-1">11. Out of Scope <a class="header-anchor" href="#_11-out-of-scope" aria-label="Permalink to &quot;11. Out of Scope&quot;">​</a></h2><ul><li>Đổi nhận diện thương hiệu hoặc giao diện tổng thể.</li><li>Thêm vào mobile các màn Admin chỉ có trên web: Trend, Crawler, Hóa đơn, Workspace Templates, Mail Batches, Mail Suppressions.</li><li>Thay đổi quyền ở backend, thêm API, đổi quy tắc nghiệp vụ.</li><li>Ghi data lên môi trường production.</li></ul><h2 id="_12-quyet-đinh-đa-chot" tabindex="-1">12. Quyết định đã chốt <a class="header-anchor" href="#_12-quyet-đinh-đa-chot" aria-label="Permalink to &quot;12. Quyết định đã chốt&quot;">​</a></h2><ul><li>Nơi seed: Postgres local và Mongo Atlas, DB <code>brandhub</code>. Chủ dự án xác nhận chỉ một mình dùng DB này.</li><li>Data cũ: sửa tại chỗ phần liên quan (chuyển Circus Digital cho <code>user177@</code>, bỏ các dòng <code>MANAGER</code> của <code>user177@</code>, sửa hồ sơ TH True Milk); phần còn lại giữ nguyên, chỉ thêm mới.</li><li>Phạm vi: cả mobile và web; mobile dùng tab dưới kết hợp drawer.</li><li>Tối đa 12 mục trong &quot;Thêm&quot; cho mỗi vai trò.</li><li>Biểu đồ Admin mobile chỉ gồm những loại web đang có, không thêm chỉ số mới.</li></ul>',44)])])}const m=t(o,[["render",a]]);export{u as __pageData,m as default};
